<?php
declare(strict_types=1);require_once __DIR__.'/config.php';session_start();if(!isset($_SESSION['admin'])){http_response_code(403);exit('Acceso denegado.');}
$q=trim((string)($_GET['q']??''));$cat=trim((string)($_GET['categoria']??''));$status=trim((string)($_GET['estado']??''));$sql='SELECT * FROM parejas WHERE 1=1';$args=[];if($q!==''){$sql.=' AND (folio LIKE ? OR representacion LIKE ? OR huapanguera_nombre LIKE ? OR huapanguero_nombre LIKE ?)';$l="%$q%";array_push($args,$l,$l,$l,$l);}if($cat!==''&&in_array($cat,CATEGORIES,true)){$sql.=' AND categoria=?';$args[]=$cat;}if(in_array($status,['pendiente_pago','confirmado','cancelado'],true)){$sql.=' AND estado_registro=?';$args[]=$status;}$sql.=' ORDER BY numero_pareja';$st=db()->prepare($sql);$st->execute($args);
header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="inscripciones_huapango_'.date('Ymd_His').'.csv"');$o=fopen('php://output','w');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,['No. pareja','Folio','Categoría','Estilo','Representación','Huapanguera','Nacimiento huapanguera','Teléfono huapanguera','Domicilio huapanguera','Huapanguero','Nacimiento huapanguero','Teléfono huapanguero','Domicilio huapanguero','Pago','Registro','Fecha']);while($r=$st->fetch()){fputcsv($o,[$r['numero_pareja'],$r['folio'],$r['categoria'],$r['estilo'],$r['representacion'],$r['huapanguera_nombre'],$r['huapanguera_fecha_nacimiento'],$r['huapanguera_telefono'],$r['huapanguera_domicilio'],$r['huapanguero_nombre'],$r['huapanguero_fecha_nacimiento'],$r['huapanguero_telefono'],$r['huapanguero_domicilio'],$r['estado_pago'],$r['estado_registro'],$r['created_at']]);}fclose($o);
